  print(f"Key: {key}, Value: {value}")

# Using break to exit a loop prematurely
for i in range(10):
  if i == 5:
    break  # Exit the loop when i is 5
  print(i)

# Using continue to skip an iteration
for i in range(5):
  if i == 2:
    continue  # Skip the iteration when i is 2
  print(i)

# Nested loops
