/**
 * Implements the Bubble Sort algorithm to sort an array of integers in ascending order.
 *
 * @param {number[]} arr The array of integers to be sorted.
 * @returns {number[]|string} The sorted array or an error message if input is invalid.
 *
 * Algorithm:
 * Bubble Sort repeatedly steps through the list, compares adjacent elements and swaps them
 * if they are in the wrong order. The pass through the list is repeated until no swaps are needed,
 * which indicates that the list is sorted.
 *
 * Time Complexity:
 * - Best Case: O(n) - when the array is already sorted.
 * - Average Case: O(n^2)
 * - Worst Case: O(n^2) - when the array is sorted in reverse order.
 *
 * Space Complexity: O(1) - It sorts the array in-place.
 */
function bubbleSort(arr) {
  // Input validation: Check if the input is an array.
  if (!Array.isArray(arr)) {
    return "Error: Input must be an array.";
  }

  // Input validation: Check if the array length exceeds the limit.
  if (arr.length > 100) {
    return "Error: Array length exceeds the maximum limit of 100.";
  }

  // Input validation: Check if the array contains only numbers within the specified range.
  for (let i = 0; i < arr.length; i++) {
    if (typeof arr[i] !== 'number' || arr[i] < -10000 || arr[i] > 10000) {
      return "Error: Array elements must be numbers between -10000 and 10000.";
    }
  }

  const n = arr.length;
  let swapped; // Flag to optimize - if no swaps occur in a pass, the array is sorted.

  do {
    swapped = false;
    for (let i = 0; i < n - 1; i++) {
      // Compare adjacent elements
      if (arr[i] > arr[i + 1]) {
        // Swap arr[i] and arr[i+1]
        let temp = arr[i];
        arr[i] = arr[i + 1];
        arr[i + 1] = temp;
        swapped = true;
      }
    }
  } while (swapped); // Continue iterating as long as swaps are made.

  return arr; // Return the sorted array.
}

// Example usage:
const unsortedArray = [5, 1, 4, 2, 8];
const sortedArray = bubbleSort(unsortedArray);
console.log("Unsorted array:", unsortedArray); // Output: Unsorted array: [ 5, 1, 4, 2, 8 ]
console.log("Sorted array:", sortedArray);   // Output: Sorted array: [ 1, 2, 4, 5, 8 ]

const unsortedArray2 = [10, -5, 0, 20, -10];
const sortedArray2 = bubbleSort(unsortedArray2);
console.log("Unsorted array:", unsortedArray2); // Output: Unsorted array: [ 10, -5, 0, 20, -10 ]
console.log("Sorted array:", sortedArray2);   // Output: Sorted array: [ -10, -5, 0, 10, 20 ]

// Example with invalid input (array length exceeding limit):
const longArray = Array.from({ length: 101 }, (_, i) => i);
const result = bubbleSort(longArray);
console.log("Result with long array:", result); // Output: Result with long array: Error: Array length exceeds the maximum limit of 100.

// Example with invalid input (non-numeric element):
